{"language": "html", "code": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AI Today & Tomorrow — NYHIMA</title>
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;700;900&family=DM+Sans:wght@300;400;500&family=DM+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
  :root {
    --navy: #0a1628;
    --crimson: #c41e3a;
    --cream: #f5f0e8;
    --gold: #d4a847;
    --slate: #4a5568;
    --light: #e8e0d0;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: var(--navy);
    color: var(--cream);
    font-family: 'DM Sans', sans-serif;
    min-height: 100vh;
    overflow-x: hidden;
  }

  .slide {
    display: none;
    min-height: 100vh;
    padding: 4rem;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    position: relative;
    animation: fadeIn 0.8s ease;
  }

  .slide.active { display: flex; }

  @keyframes fadeIn {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
  }

  /* SLIDE 1 — Title */
  #slide-1 {
    background: var(--navy);
    background-image: radial-gradient(ellipse at 20% 50%, rgba(196,30,58,0.15) 0%, transparent 60%),
                      radial-gradient(ellipse at 80% 20%, rgba(212,168,71,0.1) 0%, transparent 50%);
  }

  #slide-1 .eyebrow {
    font-family: 'DM Mono', monospace;
    font-size: 0.75rem;
    letter-spacing: 0.3em;
    color: var(--gold);
    text-transform: uppercase;
    margin-bottom: 2rem;
  }

  #slide-1 h1 {
    font-family: 'Playfair Display', serif;
    font-size: clamp(2.5rem, 6vw, 5rem);
    font-weight: 900;
    line-height: 1.1;
    color: var(--cream);
    margin-bottom: 1rem;
  }

  #slide-1 h1 span {
    color: var(--crimson);
  }

  #slide-1 .subtitle {
    font-size: 1.1rem;
    color: var(--light);
    opacity: 0.7;
    letter-spacing: 0.05em;
    margin-bottom: 3rem;
  }

  /* SLIDE 2 — Front Lines */
  #slide-2 {
    background: var(--crimson);
    background-image: radial-gradient(ellipse at center, rgba(0,0,0,0.3) 0%, transparent 70%);
  }

  #slide-2 .big-statement {
    font-family: 'Playfair Display', serif;
    font-size: clamp(2rem, 5vw, 4.5rem);
    font-weight: 700;
    line-height: 1.2;
    max-width: 900px;
    margin-bottom: 2rem;
  }

  #slide-2 .sub {
    font-size: 1.2rem;
    opacity: 0.85;
    max-width: 600px;
    line-height: 1.6;
  }

  /* SLIDE 3 — Stats */
  #slide-3 {
    background: var(--navy);
    background-image: radial-gradient(ellipse at 70% 30%, rgba(212,168,71,0.12) 0%, transparent 60%);
  }

  #slide-3 .stat-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 2rem;
    max-width: 900px;
    margin: 2rem 0;
  }

  .stat-card {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(212,168,71,0.3);
    border-radius: 4px;
    padding: 2rem;
  }

  .stat-card .number {
    font-family: 'Playfair Display', serif;
    font-size: 3rem;
    font-weight: 900;
    color: var(--gold);
    display: block;
  }

  .stat-card .label {
    font-size: 0.85rem;
    color: var(--light);
    opacity: 0.75;
    line-height: 1.5;
    margin-top: 0.5rem;
  }

  #slide-3 h2 {
    font-family: 'Playfair Display', serif;
    font-size: clamp(1.5rem, 3vw, 2.5rem);
    margin-bottom: 0.5rem;
    color: var(--cream);
  }

  #slide-3 .context {
    font-size: 0.95rem;
    color: var(--light);
    opacity: 0.6;
    max-width: 700px;
    line-height: 1.6;
    margin-top: 1rem;
  }

  /* SLIDE 4 — Clichés */
  #slide-4 {
    background: #111827;
    background-image: radial-gradient(ellipse at 30% 70%, rgba(196,30,58,0.08) 0%, transparent 60%);
    align-items: flex-start;
    text-align: left;
    padding: 3rem 4rem;
  }

  #slide-4 .header {
    font-family: 'DM Mono', monospace;
    font-size: 0.7rem;
    letter-spacing: 0.25em;
    color: var(--gold);
    text-transform: uppercase;
    margin-bottom: 1.5rem;
  }

  #slide-4 h2 {
    font-family: 'Playfair Display', serif;
    font-size: clamp(1.4rem, 2.5vw, 2rem);
    color: var(--cream);
    margin-bottom: 2rem;
    max-width: 700px;
    line-height: 1.3;
  }

  .cliche-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 0.75rem;
    width: 100%;
    max-width: 1000px;
  }

  .cliche-item {
    background: rgba(255,255,255,0.04);
    border-left: 3px solid var(--crimson);
    padding: 0.9rem 1.2rem;
    font-size: 0.9rem;
    color: var(--light);
    opacity: 0;
    transform: translateX(-10px);
    transition: opacity 0.4s ease, transform 0.4s ease;
    font-style: italic;
    line-height: 1.4;
  }

  .cliche-item.revealed {
    opacity: 1;
    transform: translateX(0);
  }

  /* SLIDE 5 — Music + Pivot */
  #slide-5 {
    background: var(--navy);
    background-image: radial-gradient(ellipse at center, rgba(212,168,71,0.08) 0%, transparent 70%);
  }

  #slide-5 .music-note {
    font-size: 4rem;
    margin-bottom: 1.5rem;
    animation: pulse 2s ease-in-out infinite;
  }

  @keyframes pulse {
    0%, 100% { transform: scale(1); opacity: 1; }
    50% { transform: scale(1.1); opacity: 0.8; }
  }

  #slide-5 .playing-label {
    font-family: 'DM Mono', monospace;
    font-size: 0.75rem;
    letter-spacing: 0.2em;
    color: var(--gold);
    text-transform: uppercase;
    margin-bottom: 1rem;
  }

  #slide-5 .pivot {
    font-family: 'Playfair Display', serif;
    font-size: clamp(1.5rem, 3vw, 2.5rem);
    max-width: 800px;
    line-height: 1.3;
    margin-top: 2rem;
    color: var(--cream);
  }

  #slide-5 .pivot span {
    color: var(--crimson);
  }

  /* Navigation */
  .nav {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    display: flex;
    gap: 0.75rem;
    z-index: 100;
  }

  .nav-btn {
    background: rgba(255,255,255,0.1);
    border: 1px solid rgba(255,255,255,0.2);
    color: var(--cream);
    padding: 0.6rem 1.4rem;
    font-family: 'DM Mono', monospace;
    font-size: 0.75rem;
    letter-spacing: 0.1em;
    cursor: pointer;
    transition: all 0.2s;
    border-radius: 2px;
  }

  .nav-btn:hover {
    background: var(--crimson);
    border-color: var(--crimson);
  }

  .nav-btn:disabled {
    opacity: 0.3;
    cursor: not-allowed;
  }

  /* Slide counter */
  .counter {
    position: fixed;
    bottom: 2rem;
    left: 2rem;
    font-family: 'DM Mono', monospace;
    font-size: 0.7rem;
    color: rgba(255,255,255,0.3);
    letter-spacing: 0.1em;
  }

  /* Action button */
  .action-btn {
    background: var(--crimson);
    border: none;
    color: white;
    padding: 0.9rem 2.5rem;
    font-family: 'DM Sans', sans-serif;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
    border-radius: 2px;
    letter-spacing: 0.05em;
    margin-top: 1rem;
  }

  .action-btn:hover {
    background: #a01830;
    transform: translateY(-1px);
  }

  .action-btn.secondary {
    background: transparent;
    border: 1px solid rgba(255,255,255,0.3);
    margin-left: 1rem;
  }

  .action-btn.secondary:hover {
    background: rgba(255,255,255,0.1);
  }

  /* Hidden YouTube iframe */
  #yt-audio {
    position: fixed;
    width: 1px;
    height: 1px;
    opacity: 0;
    pointer-events: none;
    top: -999px;
  }

  .music-status {
    font-family: 'DM Mono', monospace;
    font-size: 0.7rem;
    color: var(--gold);
    letter-spacing: 0.1em;
    margin-top: 1rem;
    min-height: 1.2rem;
  }
</style>
</head>
<body>

<!-- Hidden YouTube iframe for audio -->
<iframe id="yt-audio" src="" allow="autoplay" allowfullscreen></iframe>

<!-- SLIDE 1: Title -->
<div class="slide active" id="slide-1">
  <div class="eyebrow">New York Health Information Management Association</div>
  <h1>AI <span>Today</span> &<br>Tomorrow</h1>
  <div class="subtitle">For HIMA Professionals</div>
  <button class="action-btn" onclick="nextSlide()">Begin →</button>
</div>

<!-- SLIDE 2: Front Lines -->
<div class="slide" id="slide-2">
  <div class="big-statement">
    You are on the front lines of AI automation in healthcare.
  </div>
  <div class="sub">
    I am looking at the people most likely to be directly affected by it.<br>
    Not eventually. Now.
  </div>
</div>

<!-- SLIDE 3: The Data -->
<div class="slide" id="slide-3">
  <h2>This Is Already Happening</h2>
  <div class="stat-grid">
    <div class="stat-card">
      <span class="number">70%</span>
      <div class="label">of health systems plan to expand AI-driven automation in revenue cycle by 2026</div>
    </div>
    <div class="stat-card">
      <span class="number">30–70%</span>
      <div class="label">reduction in coding-related FTE workload once AI is fully integrated</div>
    </div>
    <div class="stat-card">
      <span class="number">$125B</span>
      <div class="label">lost annually to coding errors — the problem AI is being hired to fix</div>
    </div>
  </div>
  <div class="context">
    Autonomous medical coding is at the top of the priority list.<br>
    The question is not whether AI is coming for your workflow. It is.
  </div>
</div>

<!-- SLIDE 4: The Clichés -->
<div class="slide" id="slide-4">
  <div class="header">Things You've Been Told</div>
  <h2>Everything is going to be fine.<br>Here's how they explained it to you.</h2>
  <div class="cliche-grid" id="cliche-grid">
    <div class="cliche-item">"AI doesn't take jobs — people with AI take jobs."</div>
    <div class="cliche-item">"AI handles the routine so you can focus on the complex."</div>
    <div class="cliche-item">"Humans will always be needed for the human touch."</div>
    <div class="cliche-item">"AI will create more jobs than it destroys."</div>
    <div class="cliche-item">"It's just a tool — it depends how you use it."</div>
    <div class="cliche-item">"You just need to upskill."</div>
    <div class="cliche-item">"AI augments human judgment, it doesn't replace it."</div>
    <div class="cliche-item">"We've survived every technological revolution before."</div>
    <div class="cliche-item">"AI frees you up to do the work that really matters."</div>
    <div class="cliche-item">"The robots are here to help, not replace."</div>
    <div class="cliche-item">"AI makes you more valuable, not less."</div>
    <div class="cliche-item">"Think of AI as your assistant, not your replacement."</div>
  </div>
  <div style="margin-top:1.5rem;">
    <button class="action-btn" onclick="revealCliches()">Reveal</button>
    <button class="action-btn secondary" onclick="nextSlide()">Continue →</button>
  </div>
</div>

<!-- SLIDE 5: The Music + Pivot -->
<div class="slide" id="slide-5">
  <div class="music-note">🎵</div>
  <div class="playing-label">Don't Worry, Be Happy — Bobby McFerrin, 1988</div>
  <button class="action-btn" onclick="playAudio()">▶ Play</button>
  <div class="music-status" id="music-status"></div>
  <div class="pivot">
    You've heard every one of those reassurances.<br>
    And you're sitting here anyway.<br><br>
    Because somewhere in the back of your mind,<br>
    you're thinking — <span>yeah, but what about my job?</span><br>
    That's what we're here to talk about.
  </div>
</div>

<!-- Navigation -->
<div class="nav">
  <button class="nav-btn" id="prev-btn" onclick="prevSlide()" disabled>← Back</button>
  <button class="nav-btn" id="next-btn" onclick="nextSlide()">Next →</button>
</div>

<div class="counter" id="counter">1 / 5</div>

<script>
  let current = 1;
  const total = 5;

  function showSlide(n) {
    document.querySelectorAll('.slide').forEach(s => s.classList.remove('active'));
    document.getElementById('slide-' + n).classList.add('active');
    document.getElementById('counter').textContent = n + ' / ' + total;
    document.getElementById('prev-btn').disabled = n === 1;
    document.getElementById('next-btn').disabled = n === total;
    current = n;
  }

  function nextSlide() {
    if (current < total) showSlide(current + 1);
  }

  function prevSlide() {
    if (current > 1) showSlide(current - 1);
  }

  // Keyboard navigation
  document.addEventListener('keydown', e => {
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown' || e.key === ' ') nextSlide();
    if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') prevSlide();
  });

  // Reveal clichés one by one
  function revealCliches() {
    const items = document.querySelectorAll('.cliche-item');
    items.forEach((item, i) => {
      setTimeout(() => item.classList.add('revealed'), i * 150);
    });
  }

  // Play YouTube audio
  function playAudio() {
    const iframe = document.getElementById('yt-audio');
    // JKZ92za6Dbo — Don't Worry Be Happy
    iframe.src = 'https://www.youtube.com/embed/JKZ92za6Dbo?autoplay=1&start=0';
    document.getElementById('music-status').textContent = '♪ playing...';
    setTimeout(() => {
      document.getElementById('music-status').textContent = '';
    }, 8000);
  }
</script>

</body>
</html>
